import { supabase } from './supabase';

export interface SavedDataset {
    id: string;
    user_id: string;
    name: string;
    file_url: string;
    columns: any[];
    stats: any[];
    created_at: string;
}

export interface SavedReport {
    id: string;
    user_id: string;
    name: string;
    dataset_id: string;
    widgets: any[];
    created_at: string;
}

/**
 * Uploads a raw data file to Supabase Storage
 */
export async function uploadFile(file: File, userId: string): Promise<string | null> {
    const fileExt = file.name.split('.').pop();
    const fileName = `${Math.random().toString(36).substring(2)}.${fileExt}`;
    const filePath = `${userId}/datasets/${fileName}`;

    const { error: uploadError } = await supabase.storage
        .from('files')
        .upload(filePath, file);

    if (uploadError) {
        console.error('Error uploading file:', uploadError.message);
        return null;
    }

    const { data: { publicUrl } } = supabase.storage
        .from('files')
        .getPublicUrl(filePath);

    return publicUrl;
}

/**
 * Sanitizes an object to be JSON-safe by converting BigInt to Number
 */
function sanitizeForJSON(obj: any): any {
    if (obj === null || obj === undefined) return obj;
    if (typeof obj === 'bigint') return Number(obj);
    if (Array.isArray(obj)) return obj.map(sanitizeForJSON);
    if (typeof obj === 'object') {
        const sanitized: any = {};
        for (const key in obj) {
            sanitized[key] = sanitizeForJSON(obj[key]);
        }
        return sanitized;
    }
    return obj;
}

/**
 * Saves dataset metadata to the database
 */
export async function saveDataset(dataset: Omit<SavedDataset, 'id' | 'created_at'>) {
    const sanitizedDataset = sanitizeForJSON(dataset);
    const { data, error } = await supabase
        .from('datasets')
        .insert([sanitizedDataset])
        .select()
        .single();

    if (error) {
        console.error('Error saving dataset metadata:', error.message);
        throw error;
    }

    return data;
}

/**
 * Fetches all datasets for the current user
 */
export async function getDatasets(): Promise<SavedDataset[]> {
    const { data, error } = await supabase
        .from('datasets')
        .select('*')
        .order('created_at', { ascending: false });

    if (error) {
        console.error('Error fetching datasets:', error.message);
        return [];
    }

    return data || [];
}

/**
 * Saves or updates a report
 */
export async function saveReport(report: Omit<SavedReport, 'id' | 'created_at'>) {
    const { data, error } = await supabase
        .from('reports')
        .upsert([report])
        .select()
        .single();

    if (error) {
        console.error('Error saving report:', error.message);
        throw error;
    }

    return data;
}

/**
 * Fetches reports for a specific dataset or all user reports
 */
export async function getReports(datasetId?: string): Promise<SavedReport[]> {
    let query = supabase.from('reports').select('*').order('created_at', { ascending: false });

    if (datasetId) {
        query = query.eq('dataset_id', datasetId);
    }

    const { data, error } = await query;

    if (error) {
        console.error('Error fetching reports:', error.message);
        return [];
    }

    return data || [];
}
